const SUPPORTED_PAYLOAD_VERSION = 1;
const REQUIRED_ANSWER_FIELDS = ['העסק', 'הבעיה הכי חשובה', 'שם', 'אימייל'];
const KNOWN_ANSWER_FIELDS = [
  'העסק', 'הבעיה הכי חשובה', 'שם', 'אימייל',
  'מטרה', 'מיקום עבודה', 'יום עבודה', 'משימה חוזרת', 'שיקרה לבד',
  'מקור לקוחות', 'אחרי פנייה', 'שאלות חוזרות', 'כלים', 'כלים נוספים',
  'אתר', 'קישור לאתר', 'חסר', 'דחיפות', 'קשר נוסף',
];
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

// Re-validates deterministically inside n8n before any write or email —
// must not trust the caller, and must never invent a field that is not
// part of the real audit form.
const body = ($input.first().json.body) || {};

function invalid(reason) {
  return [{ json: { valid: 'invalid', reason, submissionId: typeof body.submissionId === 'string' ? body.submissionId : null } }];
}

if (typeof body.submissionId !== 'string' || body.submissionId.trim() === '') {
  return invalid('missing_submission_id');
}
if (typeof body.receivedAt !== 'string' || body.receivedAt.trim() === '' || isNaN(Date.parse(body.receivedAt))) {
  return invalid('missing_or_unparseable_received_at');
}
if (body.source !== 'website-audit') {
  return invalid('unsupported_source');
}
if (body.payloadVersion !== SUPPORTED_PAYLOAD_VERSION) {
  return invalid('unsupported_payload_version');
}

const answers = body.answers;
if (typeof answers !== 'object' || answers === null || Array.isArray(answers)) {
  return invalid('missing_answers');
}

for (const key of Object.keys(answers)) {
  if (!KNOWN_ANSWER_FIELDS.includes(key)) {
    return invalid('unknown_answer_field');
  }
}

for (const key of REQUIRED_ANSWER_FIELDS) {
  const value = answers[key];
  if (typeof value !== 'string' || value.trim() === '') {
    return invalid('missing_required_field');
  }
}

const email = answers['אימייל'];
if (!EMAIL_RE.test(email)) {
  return invalid('invalid_email');
}

// Normalized, flat row — every downstream node (Sheets, emails, Claude
// prompt) reads from this node instead of the old $('Webhook').body root.
const row = {
  valid: 'valid',
  submissionId: body.submissionId,
  receivedAt: body.receivedAt,
  source: body.source,
  payloadVersion: body.payloadVersion,
  processingStatus: 'received_pending_analysis',
};
for (const key of KNOWN_ANSWER_FIELDS) {
  const value = answers[key];
  row[key] = typeof value === 'string' ? value : '';
}

return [{ json: row }];

// The Lookup node (Google Sheets: Get Row(s), filtered by submissionId) has
// "Always Output Data" enabled so it still emits one item even on zero
// matches — otherwise n8n would skip everything downstream and the webhook
// would never respond. This node combines that lookup result with the
// already-validated payload (read by name from "Validate & Normalize").
const validated = $('Validate & Normalize').first().json;
const matches = $input.all().filter((item) => item.json && item.json.submissionId);
const isDuplicate = matches.length > 0;

return [{
  json: {
    ...validated,
    duplicate: isDuplicate ? 'true' : 'false',
  },
}];

